"""Compare Rust bas with the in-tree C bas during 25.R (ruling 17, O9)."""

import os
from pathlib import Path
import subprocess
import sys
import tempfile

from integer import INTEGER_ENCODINGS, INTEGER_REJECTIONS
from run import ASSEMBLER_CORPUS, SOURCES, STRICT, require

FIXTURES = Path(__file__).resolve().parent

# Inline inputs reproduce the files generated by check_integer,
# check_relocations, check_addressing and check_supplemental_encodings.
OBJECT_PARITY = (
    (FIXTURES / "exit42.s", None),
    (FIXTURES / "addressing.s", None),
    (FIXTURES / "relocations.s", None),
    (ASSEMBLER_CORPUS / "encodings.s", None),
    (ASSEMBLER_CORPUS / "sse-exit.s", None),
    (ASSEMBLER_CORPUS / "x87-exit.s", None),
    ("integer-encodings.s", "\n".join(line for line, _ in INTEGER_ENCODINGS) + "\n"),
    ("external-call.s", "call external\nglobal external\n"),
)

DIAGNOSTIC_PARITY = (
    (ASSEMBLER_CORPUS / "bad-input.s", None),
    *((f"integer-{index}.s", f"section .text\n{line}\n")
       for index, (line, _) in enumerate(INTEGER_REJECTIONS)),
    *((f"addressing-{index}.s", f"section .text\n    {line}\n")
       for index, line in enumerate((
           "mov ah, [r8]",
           "mov al, [rax+rsp*2]",
           "jmp .Lmissing",
       ))),
    *((f"supplemental-{index}.s", f"section .text\n{line}\n")
       for index, line in enumerate((
           "lock cmp dword [rax], 1",
           "lock add eax, [rax]",
           "repne stosb",
           "movss xmm1, eax",
           "fld byte [rax]",
           "mov eax, [rip + symbol@tpoff]",
           "mov eax, [symbol@tpoff]\nsymbol:",
       ))),
)


def compare(directory, oracle, bas, cases, accepted):
    differences = []
    for index, (name, inline) in enumerate(cases):
        source = directory / name
        if inline is not None:
            source.write_text(inline)
        paths = [directory / f"{index}-{producer}.o" for producer in ("c", "rust")]
        c, rust = [
            subprocess.run([binary, "-o", path, source], capture_output=True, timeout=10)
            for binary, path in zip((oracle, bas), paths)
        ]
        if accepted:
            require(c.returncode == 0, f"C bas rejected {name}: {c.stderr!r}")
            if rust.returncode != 0:
                differences.append(f"{name}: Rust bas rejected input: {rust.stderr!r}")
            elif not paths[1].is_file() or paths[0].read_bytes() != paths[1].read_bytes():
                differences.append(f"{name}: object bytes differ")
        else:
            require(c.returncode == 1 and c.stderr.startswith(os.fsencode(source) + b":"),
                    f"C bas did not give a located rejection for {name}: {c.stderr!r}")
            if (rust.returncode, rust.stderr) != (c.returncode, c.stderr):
                differences.append(
                    f"{name}: C ({c.returncode}, {c.stderr!r}), "
                    f"Rust ({rust.returncode}, {rust.stderr!r})"
                )
            elif paths[1].exists():
                differences.append(f"{name}: Rust bas wrote an object for rejected input")
    return differences


def objects_equal_c_bas(bas):
    with tempfile.TemporaryDirectory(prefix="bas-parity-") as scratch:
        directory = Path(scratch)
        oracle = directory / "c-bas"
        subprocess.run([os.environ.get("CC", "clang"), *STRICT, *SOURCES, "-o", oracle],
                       check=True, timeout=30)
        positive = directory / "accepted"
        negative = directory / "rejected"
        positive.mkdir()
        negative.mkdir()
        objects = compare(positive, oracle, bas, OBJECT_PARITY, accepted=True)
        diagnostics = compare(negative, oracle, bas, DIAGNOSTIC_PARITY, accepted=False)
        print(f"Object parity: {len(OBJECT_PARITY) - len(objects)}/{len(OBJECT_PARITY)}")
        print(f"Diagnostic parity: {len(DIAGNOSTIC_PARITY) - len(diagnostics)}/"
              f"{len(DIAGNOSTIC_PARITY)}")
        require(not objects and not diagnostics, "\n".join(objects + diagnostics))


if __name__ == "__main__":
    try:
        objects_equal_c_bas(Path(sys.argv[1]))
    except ValueError as error:
        sys.exit(f"bas_parity::objects_equal_c_bas FAIL\n{error}")
